    themeNote: ['', ''],
    // open dataset (AKUDENTAL)
    openData: ['Conjunto de datos abierto', 'Open dataset'],
    does6: ['Incluye un subconjunto de un conjunto de datos publicado (AKUDENTAL, 36 radiografías panorámicas reales y anonimizadas con anotación experta) para ver el flujo completo con imágenes reales.', 'Includes a subset of a published dataset (AKUDENTAL, 36 real anonymised panoramic radiographs with expert annotation) so the complete workflow can be seen on real images.'],
    openBanner: ['Conjunto de datos abierto cargado: {name}, {n} radiografías panorámicas reales de adultos, anonimizadas y publicadas con aprobación ética. Licencia {lic}: solo uso académico no comercial.', 'Open dataset loaded: {name}, {n} real adult panoramic radiographs, anonymised and published with ethics approval. Licence {lic}: non-commercial academic use only.'],
    loadOpen: ['Cargar conjunto abierto (AKUDENTAL, 36 casos)', 'Load open dataset (AKUDENTAL, 36 cases)'],
    removeOpen: ['Quitar conjunto abierto', 'Remove open dataset'],
    loadOpenOpg: ['Cargar conjunto abierto (DentalOPG-1550, 24 casos)', 'Load open dataset (DentalOPG-1550, 24 cases)'],
    loadOpenFullOpg: ['Cargar el conjunto completo (1 525 casos, ~197 MB)', 'Load the complete set (1,525 cases, ~197 MB)'],
    openBannerOpg: ['Conjunto de datos abierto cargado: {name}, {n} radiografías panorámicas reales con 14 clases de hallazgos etiquetadas por los autores (caries, obturación, corona, puente, conducto, absceso apical, periodontitis, resto radicular, ausencias, impactaciones). Licencia {lic}: uso comercial permitido con atribución. Los nombres de archivo originales llevaban nombres de pacientes: PanoramIA los eliminó y conservó solo la edad.',
      'Open dataset loaded: {name}, {n} real panoramic radiographs with 14 finding classes labelled by the authors (caries, filling, crown, bridge, root canal, apical abscess, periodontitis, broken-down root, missing teeth, impactions). Licence {lic}: commercial use allowed with attribution. The original file names carried patient names: PanoramIA removed them and kept only the age.'],
    dsCommercialOk: ['CC BY 4.0: se permite el uso comercial con atribución. Este es el linaje de datos públicos que puede entrar en el producto.', 'CC BY 4.0: commercial use allowed with attribution. This is the public-data lineage that may enter the product.'],
    dsOpgSubjectsText: ['1 525 radiografías de exámenes OPG rutinarios (1 550 en la colección original); edad por imagen 1–85 años (mediana 28), incluye dentición mixta en 95 imágenes; sexo no publicado. Un solo equipo (todas las imágenes 2871 × 1536).', '1,525 radiographs from routine OPG examinations (1,550 in the original collection); age per image 1–85 years (median 28), mixed dentition in 95 images; sex not published. One device (all images 2871 × 1536).'],
    dsOpgEthicsText: ['La ficha del conjunto no declara la aprobación ética. Los nombres de archivo originales incluían nombre y edad del paciente: PanoramIA renombró todos los archivos y conservó solo la edad. Úselo con esa cautela y cítelo siempre.', 'The dataset page does not state the ethics approval. The original file names included patient name and age: PanoramIA renamed every file and kept only the age. Use it with that caution and always cite it.'],
    dsOpgAnnotationsText: ['Cajas de una sola fuente (revisadas por un tecnólogo médico) para 14 clases: caries 1 578, ausencias 1 547, conductos 894, restos radiculares (BDR) 810, obturaciones 738, coronas 636, terceros molares no erupcionados 316, impactación horizontal 277, distoangular 118, abscesos apicales 98, periodontitis 54, puentes 56; dientes normales solo en 286 imágenes y sin número FDI (PanoramIA lo estima por posición).', 'Single-source boxes (reviewed by a medical technologist) for 14 classes: caries 1,578, missing teeth 1,547, root canals 894, broken-down roots (BDR) 810, fillings 738, crowns 636, unerupted third molars 316, horizontal impaction 277, distoangular 118, apical abscesses 98, periodontitis 54, bridges 56; normal teeth only in 286 images and without FDI numbers (PanoramIA estimates them by position).'],
    dsOpgSelectionText: ['24 de 1 525 imágenes para el subconjunto incrustado: las 16 con más hallazgos raros (abscesos, puentes, periodontitis, impactaciones) y 8 tomadas a intervalos regulares (tools/curate_dentalopg.py).', '24 of 1,525 images for the embedded subset: the 16 with most rare findings (abscesses, bridges, periodontitis, impactions) and 8 taken at regular intervals (tools/curate_dentalopg.py).'],
    dsOpgProcessingText: ['Originales BMP convertidos a gris de 8 bits y reducidos a 1400 px (conjunto completo) o 1000 px (subconjunto incrustado). Las cajas se dibujaron en copias estiradas a 640 × 640 y se reescalaron. Los números FDI son estimaciones por orden desde la línea media, no vienen de la fuente.', 'BMP originals converted to 8-bit grayscale and reduced to 1400 px (complete set) or 1000 px (embedded subset). Boxes were drawn on 640 × 640 stretched copies and rescaled. FDI numbers are estimates by order from the midline, not given by the source.'],
    loadOpenFull: ['Cargar el conjunto completo (333 casos, ~37 MB)', 'Load the complete set (333 cases, ~37 MB)'],
    loadOpenFullHelp: ['El conjunto completo se descarga desde el servidor que sirve la aplicación (por ejemplo GitHub Pages); no está disponible al abrir el archivo HTML directamente.', 'The complete set is downloaded from the server that serves the app (for example GitHub Pages); it is not available when the HTML file is opened directly.'],
    openProgress: ['Cargando {done} de {total}…', 'Loading {done} of {total}…'],
    openLoaded: ['{n} casos cargados', '{n} cases loaded'],
    openLoadFailed: ['No se pudo descargar el conjunto completo.', 'The complete set could not be downloaded.'],
    extRef: ['Referencia externa', 'External reference'],
    extRefHelp: ['Anotaciones de un solo experto tomadas del conjunto publicado; no fueron releídas ni adjudicadas en PanoramIA. Lector 1 y Lector 2 están vacíos a propósito: practique la lectura ciega y compare después.', 'Single-expert annotations taken from the published dataset; not double-read or adjudicated inside PanoramIA. Reader 1 and Reader 2 are empty on purpose: practise blind reading, then compare.'],
    showRef: ['Estructuras de referencia', 'Reference structures'],
    refLegendOpg: ['Cajas del conjunto DentalOPG-1550 con el color de cada categoría (caries, obturación, corona, puente, conducto, absceso apical, periodontitis, resto radicular, ausencia, impactación); dientes punteados = FDI estimado por posición. Anotación de la fuente, no un resultado de IA.', 'DentalOPG-1550 boxes in each category colour (caries, filling, crown, bridge, root canal, apical abscess, periodontitis, broken-down root, missing, impaction); dashed teeth = FDI estimated by position. Source annotation, not an AI result.'],
    refLegend: ['Dientes (FDI) · Implante · Puente · Obturación o corona — anotación experta del conjunto AKUDENTAL, no un resultado de IA', 'Teeth (FDI) · Implant · Bridge · Filling or crown — expert annotation from the AKUDENTAL dataset, not an AI output'],
    refKind_implant: ['Implante (AKUDENTAL)', 'Implant (AKUDENTAL)'], refKind_bridge: ['Puente (AKUDENTAL)', 'Bridge (AKUDENTAL)'], refKind_filling_crown: ['Obturación o corona (AKUDENTAL)', 'Filling or crown (AKUDENTAL)'],
    teethLabelled: ['Dientes etiquetados por la referencia', 'Teeth labelled by the reference'],
