    datasetCard: ['Ficha del conjunto de datos', 'Dataset card'],
    dsLicence: ['Licencia', 'Licence'], dsCitation: ['Cita', 'Citation'], dsSource: ['Fuente', 'Source'], dsEthics: ['Ética', 'Ethics'], dsProcessing: ['Procesamiento', 'Processing'], dsAnnotations: ['Anotaciones', 'Annotations'], dsSelection: ['Selección del subconjunto', 'Subset selection'], dsSubjects: ['Sujetos', 'Subjects'],
    dsSubjectsText: ['333 adultos (190 mujeres, 143 hombres); edad y sexo por imagen no publicados. Dos equipos panorámicos del Hospital Odontológico de la Universidad de Akdeniz, Antalya, Türkiye.', '333 adults (190 female, 143 male); per-image age and sex not published. Two panoramic units at Akdeniz University Dental Hospital, Antalya, Türkiye.'],
    dsEthicsText: ['Comité de Ética de Investigación Clínica de la Universidad de Akdeniz (KAEK-72); retrospectivo, anonimizado, consentimiento exonerado.', 'Akdeniz University Clinical Research Ethical Committee (KAEK-72); retrospective, anonymised, consent waived.'],
    dsAnnotationsText: ['Un experto por imagen: 32 dientes por número FDI (polígonos y cajas), implantes, puentes y obturaciones o coronas. 9 956 instancias en el conjunto completo.', 'One expert per image: 32 teeth by FDI number (polygons and boxes), implants, bridges and fillings or crowns. 9,956 instances in the complete set.'],
    dsProcessingText: ['Conversión a escala de grises de 8 bits, reducción a 1400 px de ancho, JPEG calidad 78; coordenadas reescaladas. Revisión visual de texto grabado en las 36 imágenes del subconjunto (solo marcadores de lado).', 'Converted to 8-bit grayscale, downscaled to 1400 px wide, JPEG quality 78; coordinates rescaled. Visual check for burned-in text on the 36 subset images (side markers only).'],
    dsSelectionText: ['36 de 333 imágenes elegidas por reglas deterministas y reproducibles (tools/curate_akudental.py): 8 con implantes, 7 con puentes, 8 con los cuatro terceros molares presentes, 6 parcialmente edéntulas, 7 típicas.', '36 of 333 images chosen by deterministic, reproducible rules (tools/curate_akudental.py): 8 with implants, 7 with bridges, 8 with all four third molars present, 6 partially edentulous, 7 typical.'],
    dsNC: ['No comercial: estas imágenes pueden usarse en docencia e investigación, nunca en un producto de pago. El producto comercial usará únicamente datos dominicanos con consentimiento y base legal propia.', 'Non-commercial: these images may be used in teaching and research, never in a paid product. The commercial product will use only consented Dominican data with its own legal basis.'],
    helpOpenData: ['Conjuntos de datos abiertos', 'Open datasets'],
    helpOpenIntro: ['El prototipo incluye un conjunto de datos publicado para que el flujo completo se vea con radiografías reales. Cada caso conserva su procedencia, licencia y anotación de origen.', 'The prototype includes one published dataset so the complete workflow can be seen on real radiographs. Each case keeps its provenance, licence and source annotation.'],
    helpOpenOthers: ['Otros conjuntos públicos evaluados: DENTEX (MICCAI 2023, 1005 panorámicas con caries, lesiones periapicales y dientes retenidos; CC BY-NC-SA 4.0; descarga desde Zenodo o Hugging Face) y Tufts Dental Database (1000 panorámicas; requiere acuerdo de licencia). Pueden importarse con el asistente de importación una vez descargados de su fuente oficial.', 'Other public sets reviewed: DENTEX (MICCAI 2023, 1,005 panoramics with caries, periapical lesions and impacted teeth; CC BY-NC-SA 4.0; download from Zenodo or Hugging Face) and the Tufts Dental Database (1,000 panoramics; licence agreement required). They can be imported with the import wizard once downloaded from their official source.'],
    externalTR: ['Conjunto externo (Türkiye)', 'External dataset (Türkiye)'],
