    // geometry suggestions
    geomTitle: ['Sugerencias a partir de la anatomía delimitada', 'Suggestions from the outlined anatomy'],
    geomNeedsCase: ['Vincule un caso para que el semáforo use las estructuras delimitadas en Anotar.', 'Link a case so the traffic light can use the structures outlined in Annotate.'],
    geomLead: ['Cálculos geométricos transparentes sobre los contornos y líneas que usted (o la referencia externa) dibujó. Son sugerencias: confírmelas o corríjalas en el formulario.', 'Transparent geometric computations on the outlines and lines you (or the external reference) drew. They are suggestions: confirm or correct them in the form.'],
    g_winter: ['Ángulo entre los ejes largos del tercer y segundo molar: {a}° → {cls}', 'Angle between the long axes of the third and second molars: {a}° → {cls}'],
    g_winterRule: ['Convención: vertical −10…10°, mesioangular 11…79°, horizontal 80…100°, distoangular −11…−79°; positivo = corona inclinada hacia mesial. Eje por análisis de componentes principales del contorno.', 'Convention: vertical −10…10°, mesioangular 11…79°, horizontal 80…100°, distoangular −11…−79°; positive = crown tilted mesially. Axis from principal-component analysis of the outline.'],
    g_depth: ['Punto más oclusal del tercer molar respecto al plano oclusal y la línea cervical del segundo molar → posición {d}', 'Most occlusal point of the third molar relative to the occlusal plane and the second-molar cervical line → position {d}'],
    g_depthRule: ['A: a la altura o por encima del plano oclusal; B: entre el plano oclusal y la línea cervical; C: por debajo de la línea cervical.', 'A: at or above the occlusal plane; B: between the occlusal plane and the cervical line; C: below the cervical line.'],
    g_ramus: ['Corona del tercer molar dentro de la rama: {pct} % → clase {cls}', 'Third-molar crown within the ramus: {pct} % → class {cls}'],
    g_ramusRule: ['I: corona por delante del borde anterior de la rama; II: cubierta en parte; III: totalmente dentro de la rama. La clase I supone además espacio suficiente, que la línea no mide.', 'I: crown in front of the anterior ramus border; II: partly covered; III: fully within the ramus. Class I also assumes sufficient space, which the line does not measure.'],
